import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"Configuration Directory","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/attribute/configuration.md","filePath":"en/modules/attribute/configuration.md","lastUpdated":null}'),d={name:"en/modules/attribute/configuration.md"};function n(r,e,l,o,c,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="configuration-directory" tabindex="-1">Configuration Directory <a class="header-anchor" href="#configuration-directory" aria-label="Permalink to &quot;Configuration Directory&quot;">​</a></h1><p>EmakiAttribute configuration consists of the main config, attribute definitions, damage types, conditions, lore formats, and attribute balance data. Define a stable attribute naming convention before expanding damage types and equipment sources.</p><h2 id="default-directory-structure" tabindex="-1">Default directory structure <a class="header-anchor" href="#default-directory-structure" aria-label="Permalink to &quot;Default directory structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiAttribute/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── attribute_balance.yml</span></span>
<span class="line"><span>├── attributes/</span></span>
<span class="line"><span>├── damage_types/</span></span>
<span class="line"><span>├── conditions/</span></span>
<span class="line"><span>├── lore_formats/</span></span>
<span class="line"><span>├── presets/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>├── lang/</span></span>
<span class="line"><span>└── data/</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>Main config: default resources, damage interception, regeneration, scaling curves, and vanilla damage mappings.</td></tr><tr><td><code>attribute_balance.yml</code></td><td>Attribute score and balance semantics parameters.</td></tr><tr><td><code>attributes/</code></td><td>Individual attribute definitions.</td></tr><tr><td><code>damage_types/</code></td><td>Damage pipelines, such as physical, projectile, and spell.</td></tr><tr><td><code>conditions/</code></td><td>Attribute read conditions (PDC read rules).</td></tr><tr><td><code>lore_formats/</code></td><td>Attribute display format templates.</td></tr><tr><td><code>presets/</code></td><td>Attribute preset definitions.</td></tr><tr><td><code>gui/</code></td><td>Attribute points GUI configuration (<code>attribute_points.yml</code>).</td></tr><tr><td><code>lang/</code></td><td>Language files; bundled <code>zh_CN.yml</code> and <code>en_US.yml</code>.</td></tr><tr><td><code>data/</code></td><td>Runtime data, for example <code>data/parent_attributes/&lt;UUID&gt;.yml</code>; usually not edited manually.</td></tr></tbody></table><h2 id="main-config-fields" tabindex="-1">Main config fields <a class="header-anchor" href="#main-config-fields" aria-label="Permalink to &quot;Main config fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>Config version maintained by default resource sync.</td></tr><tr><td><code>language</code></td><td>Language file id.</td></tr><tr><td><code>release_default_data</code></td><td>Whether bundled sample attributes, damage types, read rules, lore formats, and balance data are released. Enabled by default.</td></tr><tr><td><code>attribute_sources.read_lore_attributes</code></td><td>Whether item attributes are parsed from Lore. Enabled by default.</td></tr><tr><td><code>attribute_sources.read_pdc_attributes</code></td><td>Whether item attributes are read from PDC. Enabled by default.</td></tr><tr><td><code>attribute_sources.require_lore_pdc_match</code></td><td>Whether Lore and PDC must match per attribute ID. Disabled by default.</td></tr><tr><td><code>hard_lock_damage</code></td><td>Whether unmapped vanilla damage is intercepted.</td></tr><tr><td><code>default_damage_type</code></td><td>Fallback damage type.</td></tr><tr><td><code>projectile_damage_type</code></td><td>Default damage type used when cached projectile hits are resolved. Defaults to <code>projectile</code>, but can point to another loaded damage type such as <code>physical</code>.</td></tr><tr><td><code>vanilla_event_damage</code></td><td>Vanilla event damage takeover settings. When enabled, vanilla side effects are preserved and the final damage is replaced; when disabled, compatibility synthetic damage mode is used.</td></tr><tr><td><code>same_signature_ignores_invulnerability</code></td><td>Whether multi-hit attacks from the same attacker under the same attribute snapshot signature and damage type bypass the vanilla invulnerability window. <code>window_ms</code> is the batch window, default 500 ms.</td></tr><tr><td><code>attack_speed.scope</code></td><td>Attack speed cooldown scope. <code>global</code> (default) lets EmakiAttribute manage every attack, deriving the cooldown from the current vanilla <code>ATTACK_SPEED</code> for items without an EmakiAttribute attack speed value. <code>attribute_only</code> intercepts only items that declare an EmakiAttribute attack speed value and leaves every other item to vanilla.</td></tr><tr><td><code>regen_interval_ticks</code></td><td>Resource regeneration interval.</td></tr><tr><td><code>sync_delay_ticks</code></td><td>Delay before syncing attributes to Bukkit.</td></tr><tr><td><code>health_display_scaling</code></td><td>Client health bar display compression. It changes only client-side display, not real max health, current health, or damage calculation.</td></tr><tr><td><code>default_profile</code></td><td>Default resources and attributes.</td></tr><tr><td><code>synthetic_hit_feedback</code></td><td>Knockback and hurt sound feedback after vanilla damage interception.</td></tr><tr><td><code>scaling_curves</code></td><td>Rules for diminishing returns after thresholds.</td></tr><tr><td><code>allowed_damage_causes</code></td><td>Bukkit <code>DamageCause</code> to attribute damage mappings.</td></tr></tbody></table><h2 id="item-attribute-source-policy" tabindex="-1">Item attribute source policy <a class="header-anchor" href="#item-attribute-source-policy" aria-label="Permalink to &quot;Item attribute source policy&quot;">​</a></h2><p><code>attribute_sources</code> controls whether item attributes are read from Lore, PDC, or both, and whether both sources must validate each other:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">attribute_sources</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  read_lore_attributes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  read_pdc_attributes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  require_lore_pdc_match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>The default preserves the legacy behavior: all enabled Lore and PDC sources contribute to the item snapshot. When <code>require_lore_pdc_match</code> is enabled, values are compared per attribute ID:</p><ul><li>Present in both sources with equal values: count the attribute once.</li><li>Present in both sources with different values: reject the attribute.</li><li>Present in only one source: reject the attribute.</li><li>Fixed and spread/range values use the same matching rule.</li></ul><p>Match mode requires both read switches. Precheck emits a warning when either source is disabled. If both sources are disabled, default, temporary, and other entity-level sources remain available, but equipped items contribute no Lore/PDC attributes.</p><h2 id="vanilla-damage-mapping" tabindex="-1">Vanilla damage mapping <a class="header-anchor" href="#vanilla-damage-mapping" aria-label="Permalink to &quot;Vanilla damage mapping&quot;">​</a></h2><p><code>allowed_damage_causes</code> decides which Bukkit <code>DamageCause</code> values enter attribute resolution:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowed_damage_causes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cause</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">FALL</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    damage_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">physical</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cause</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">LAVA</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    damage_type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">physical</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>cause</code></td><td>Bukkit <code>DamageCause</code> name.</td></tr><tr><td><code>damage_type</code></td><td>Damage type id from <code>damage_types/*.yml</code>.</td></tr><tr><td><code>enabled</code></td><td>Whether this mapping is active.</td></tr><tr><td><code>damage</code></td><td>Optional base damage before the attribute pipeline. When omitted, the vanilla damage value already computed by the server is used, which suits fall, explosion, burning, drowning, and other height- or state-dependent sources.</td></tr></tbody></table><p>When <code>hard_lock_damage</code> is <code>true</code>, unmapped vanilla damage falls back to <code>default_damage_type</code>. When it is <code>false</code>, unmapped damage keeps vanilla behavior.</p><h2 id="suggested-edit-order" tabindex="-1">Suggested edit order <a class="header-anchor" href="#suggested-edit-order" aria-label="Permalink to &quot;Suggested edit order&quot;">​</a></h2><ol><li>Define attribute ids and display formats in <code>attributes/</code>.</li><li>Add default values to <code>default_profile</code>.</li><li>Configure damage pipelines in <code>damage_types/</code>.</li><li>Tune score weights in <code>attribute_balance.yml</code>.</li><li>Write attributes from equipment, gems, strengthening, forging, or item modules.</li><li>Use <code>/ea lint</code> to check configuration.</li><li>Use <code>/ea preview</code> or <code>/ea dump</code> to verify final player attributes.</li></ol>`,20)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
